// Speaker names are subtitle metadata; the speech adapter receives only line text.
export const conversations={
 c201:{start:[
  ['老鱼','豚师，我收拾车库翻出一把钥匙，是观沙岭那间旧店的。章鱼这两天给我打了电话，说有人换了门锁，还进去翻过东西。她一个人问不出什么，想让我们回来看看。'],
  ['豚师','她还守着那间店？我走的时候说先关几个月，后来忙起来，连钥匙放哪儿都忘了。'],
  ['攀哥','关门的是生意，房租和电费可没跟着关。这几年是章鱼在管。你先开车过桥，到了把事情问清楚，别上来就喊海豚帮回来了。'],
  ['豚师','我也没准备剪彩。先看锁是谁换的，再看看还有什么能用。要是有人把我的椅子卖了，这事就大了。'],
  ['老鱼','你的椅子腿早断了，章鱼还留着。走银盆岭大桥就能过去，店在北京御园附近。今天不用赶，路上买点吃的，人家不是在那儿等你发号施令。']
 ],end:[
  ['仙人','你们真把灯弄亮了。我还以为得等章鱼找电工。她出去办事了，知道你回来，让我先看着这里。'],
  ['豚师','柜子被翻过，照片和旧账倒都没丢。有人专门找文件。你见过他们吗？'],
  ['仙人','两个人，拿着一张旧公司的资料来问，说有东西一直没交接完。我不认得他们，也没让他们进。第二天就看见门锁换了。'],
  ['攀哥','那就先别再动柜子。我们看看附近的人最近遇到什么事，再问章鱼。好几年没回来，光看一间屋子猜不出现在的情况。']
 ]},
 c202:{start:[
  ['仙人','回来得正好，有三件急事需要人帮忙。御园车库被一辆旧车堵了，便利店刚卸的货又让人拿走，旁边还有个喝醉的，一直堵着店门骂人。'],
  ['豚师','我今天回来认门，怎么听着像来上班的？'],
  ['仙人','因为你不在的时候，章鱼每天就忙这些。店主说谁把货追回来给一百，挪车和帮忙看门也给辛苦钱。不想白忙就先做，钱当面结。'],
  ['攀哥','先把车挪出去，别停在另一户门口。拿货的人还没走远，追上把东西截回来就行。喝醉那个先劝到路边，真动手了再拦，别把店主的门也砸了。'],
  ['豚师','行，先挣钱。海豚帮终于有一个不用先垫钱的项目了。']
 ],end:[
  ['章鱼','车库能进了，店主也拿回货了。我刚回来，就听他们说你在门口忙了半天。辛苦钱结了吧？'],
  ['豚师','结了，比我在北辰第一天有出息。你这些年就一个人处理这些事？'],
  ['章鱼','也不是一个人，附近谁有空谁搭把手。你以前总说这里是咱们的，后来大家出事找不到你，自然就去找别人了。'],
  ['豚师','这个我认。店里的文件又是怎么回事？仙人说有人问过旧公司。'],
  ['章鱼','我也没看懂他们给的那张纸。先带你去地下车库，柜子里还留着当年的东西。你别急着给过去下结论，自己看看。']
 ]},
 c203:{start:[
  ['章鱼','车库西边有个零四号储物柜，我们关店时把杂物放进去了。东边墙上那幅涂鸦也还在，只是灯坏了，你得把两路照明打开。'],
  ['豚师','那几个拿手电的又是谁？看着不像来取车的。'],
  ['章鱼','替收购代理看东西的人。这几天就在里面找柜子。西边的灯和东边分开，暗处不容易被看见，开灯才能看清记录。你自己挑时机，别正对着人走。'],
  ['攀哥','开灯以后他们看得更远，记下柜号就可以把西边再关掉。蹲着从背后靠近，按互动能制服落单的人。真被看见，先打断拿手台呼叫的那个；支援来了就绕墙脱身，别守着柜子硬打。'],
  ['豚师','柜子锁了怎么办？我没带那把小钥匙。'],
  ['章鱼','锁锈了，柜门也早该换。打开或者拆掉都行，里面又不是古董。倒是外墙和停着的车，别顺手全拆了。']
 ],end:[
  ['豚师','四个名字都在。海豚怎么画成这样，谁手这么歪？'],
  ['章鱼','你。画完说这是冲浪，不许我们改。那时候我们还注册了公司，叫海豚旧友设备服务，你负责起名字，攀哥跑手续，RY 管账。'],
  ['豚师','我一直以为店关了，公司也就没了。后来 RY 在北辰做那些生意，我只当他另起炉灶。'],
  ['章鱼','这就是你和他的区别。他走之前还在问欠款什么时候结，你走之前问的是钥匙谁收着。不是说他什么都对，是你确实漏掉了一段。'],
  ['攀哥','回店吧。阿松他们有几台坏设备需要修，顺便把旧公司的事问明白。光坐着回忆，饭钱也不会自己长出来。']
 ]},
 c204:{start:[
  ['Dina','先说一笔实在的钱。旧公司要继续留着，补登记、做原件保全，再把欠下的维修费清掉，一共一万零三百。我把报价拆开核过了，没算请人守店和买装备。'],
  ['豚师','帮里两万零二，付完不是还剩不少？'],
  ['Dina','有一万得留作周转，不能今晚全掏空。帮费最多出一万零二，差的两百九十八，你从现在开始自己挣。修设备、收营业款，街上捡的钱也记账；以前兜里那点不算你这次干的活。'],
  ['豚师','行，头一次听到当帮主还有最低营业额。剩下的钱我赚，工具和饭钱也从兜里出，别再给人开空头支票。'],
  ['章鱼','阿松的扫码机、阿福的音箱，还有小武送货用的对讲机，都等着修。以前就是在这张台子上接活的，工具还齐，先把店开起来试一晚。'],
  ['豚师','我记得我负责收钱，修东西是你们的事。'],
  ['攀哥','简单的接触不良而已，我在旁边看着。拧到合适的位置就停，别一兴奋把螺丝拧穿。每单六十，失误多了品质会降，结钱也少。客人在等，开工吧。'],
  ['章鱼','要是换一套台面配件，调起来会容易些，也能接九十块的活。花不花这个钱你自己算。以后营业款先留柜台，回来再收。'],
  ['豚师','这我听明白了：用钱买工具，工具再挣钱。比“先借我一点，明天肯定还”靠谱。'],
  ['攀哥','修好了再说。人家等着拿设备，不是来听你开业讲话的。']
 ],end:[
  ['Dina','三个人说的事我核对过了。旧公司没完全注销，还持有一份仓储和配送合同。收购方买的不是这间破店，是合同里那部分服务权益。'],
  ['豚师','那他们翻柜子，是找合同？'],
  ['Dina','找四个最初签字人的原件，还有公司章。缺了这些，交易走不下去。阿松最近还看见挂旧公司物流标签的车，说明有人已经在准备交接。'],
  ['章鱼','设备修好了，店至少又能养一点日常开销。卖不卖权益是另一回事，别一听有大钱，就把正在做的事全停了。'],
  ['听歌','今晚有一辆相关的车在茶子山停车区等人。我去查司机，你们去看看交接的到底是什么。先把这条线接上，再谈钱怎么分。']
 ]},
 c205:{start:[
  ['听歌','停车区有三辆配送车，只有一辆挂着海豚旧友的旧标签，后面还装着两箱交接记录。代理准备今晚把记录带走，明天我们连对账的底都找不到。'],
  ['Dina','先看清楚车，别把别人的货当我们的。这批记录属于旧公司，先拿回来核对，里面有收购编号，也能查到办公室的资料。'],
  ['豚师','认完以后呢？别又让我陪着司机绕一晚上。'],
  ['攀哥','逼停车，再夺车。可以超到前面堵路，也可以控制着撞，车还得运东西，别给撞成废铁。它开到尽头会停，不用死追。'],
  ['炫神','夺到车以后往商业后勤层开，那儿能卸货，Dina 在接。代理肯定有人追，想甩开就利用路口和停着的车，别跟他们比谁撞得响。'],
  ['豚师','先认车，截车，自己开回来。行，这回至少拿到的是一车东西，不是一句“再去下一个地方”。']
 ],end:[
  ['Dina','调度那份签收底单和箱子里的记录对上了，交易单位是茶湾商厦，编号 H 零四。原来公司的采购和欠款都在这里，现在不怕代理挑着几页给我们看。'],
  ['豚师','车也回来了，追我的那两辆就不算了吗？'],
  ['炫神','算你今天的驾驶记录。下次能不能少用挡风玻璃找路。车留着能开，货没毁就已经不错了。'],
  ['Dina','下一步去办公室拿合同和邮件，确定 RY 到底同意了哪些事。走中庭北边电梯下到 B 一，员工楼梯在另一头，别从街上绕。纸上的链条接全，再把四个人叫到一起。']
 ]},
 c206:{start:[
  ['Dina','办公室的打印室留着合同页，右侧工位的电脑上有交割邮件。拍下这两处，金额、代理和 RY 的关系就都清楚了。其他资料可以看，不用把每张纸搬走。'],
  ['豚师','大厅那道门锁着。我先把它打开？'],
  ['攀哥','员工楼梯通到 B 一，后勤台上有临时门卡，能绕回大厅开门。想破门也能过去，动静大，巡逻的人就会来，自己判断什么时候开。'],
  ['Dina','合同要复印，邮件要导出，都得在设备旁待一会儿。有人正盯着设备，你就没法安心操作。等他转身，或者从背后制服他。要是听见手台呼叫，赶紧打断，门口还会来人；绕隔墙藏住，等他们搜索过去再回来。'],
  ['豚师','我懂。先看人走到哪儿，再挑时机拿东西。复制完走员工楼梯撤，不用把整层楼打空。'],
  ['Dina','邮件导出的时候系统会响，藏不住了。文件拿好，沿员工楼梯下到后勤层，从那里出街，我在外面接。']
 ],end:[
  ['Dina','合同和邮件对得上，RY 确实在推动收购，金额和条件也没有藏。他认为旧公司没人经营，卖掉就能结清过去的事。'],
  ['豚师','他怎么不直接来问？'],
  ['攀哥','你们在北辰刚打了一架，谁都没觉得现在能好好坐下来。不是理由，但至少知道他为什么让代理来。代理换锁、翻柜子，是把“交接”当成已经谈好了。'],
  ['听歌','邮件里有一条旧备注：公司章和原始文件，暂存北京御园豚师家。那是你搬走以前的地址，不是北辰现在住的地方。'],
  ['豚师','我想起来一半了。当年老怕印章丢，专门买过一个铁盒。先去旧家拿出来，再把四个人叫到一起，别让代理替我们谈。']
 ]},
 c207:{start:[
  ['小朋友','我陪你过来，不是怕你打不过谁，是怕你又说“我记得”，然后把整栋楼找一遍。这里真是你以前住的家？'],
  ['豚师','嗯，我们最早就是挤在这里吃饭、打游戏，第二天去店里修东西。后来攀哥和 RY 搬出去，店也慢慢不做了，我才去北辰。'],
  ['小朋友','那重要东西总得有个固定地方吧。照片、卡片先翻翻，可能留了记号。电脑和外卖单你想看也能看，不用每样都找齐。'],
  ['豚师','我记得盒子不在柜子里。当时大家都担心随手拿出去又忘了放回去，最后想了个很蠢、但确实没丢的办法。'],
  ['小朋友','先把办法想起来。我去门口站着，今天你说“找东西”和“装修”，我已经不敢当成两件事听了。']
 ],end:[
  ['小朋友','原件、公司章，还有你们四个人的签字，真的都在。盒子外面还贴着“谁拿谁记账”，你们怕是从来没照做过。'],
  ['豚师','这次记。盒子交 Dina，我们先回店。墙嘛……以后装修不用请人拆了，省一笔。'],
  ['小朋友','省下那笔先修店，别再靠一句“以后”拖着。你现在知道谁一直替你看这些地方了，至少这次把人家的事当回事。'],
  ['豚师','知道。我今天回来，终于不是只想看自己当年多好玩了。把盒子抱稳，门口那条路已经打通，走那边出去。']
 ]},
 c208:{start:[
  ['Dina','原件齐了。之前那笔一万零三百也得结：帮里出一万零二，你挣的两百九十八补余下的。我就在柜台旁边，钱够了过来结账；不够先接加急维修单，营业款也可以收。不是给代理的人花钱，是让这间店有资格继续开。'],
  ['章鱼','我不反对拿钱，我反对有人把锁一换，就当这里已经卖了。屋里的东西、我们留下的日子，不在那张合同里。'],
  ['豚师','那就先不签。今天这间店已经能接活了，慢点也能养，不是非得现在把过去都折成一笔钱。'],
  ['听歌','代理的人还在茶子山装车，说今晚要拿走原件。我盯着他们，先把账结好；等他们往店里开，我会通知，留半分钟给你们摆车和落卷帘。'],
  ['攀哥','Dina 护文件，肝脏跟你守入口。旧车可以挡在店外，卷帘放下来也能拖住第一批。还有阿松、阿福，要请他们回来守店，记得把工钱给够。'],
  ['豚师','这次不喊兄弟白干。该加固加固，该请人请人。把准备做完再让他们进，我也想试试当一个不欠工资的帮主。']
 ],end:[
  ['肝脏','文件还在，Dina 没松手。门面让车撞坏了，侧边还能走。人都退到街口去了，先别追，看看自己人有没有伤着。'],
  ['Dina','人没事。店面修一下能正常营业，没修之前也能接少量活。收购的钱我会继续算，但签字的事，必须四个人当面决定。'],
  ['章鱼','RY 听说代理动手了，刚给我打电话。他说明早带自己那份文件到江边，让我们把账和话一起说清楚。'],
  ['豚师','行。他不回来我也不强求，旧公司的事别再让别人传来传去。门的钱先记我这里，明天见完他，回来修。']
 ]},
 c209:{start:[
  ['攀哥','到湘江步道去吧，章鱼和 RY 已经在那儿。原件装进包里了，这次我们四个人都在，不缺谁，也不让谁替另一个人答应。'],
  ['豚师','我要是忍不住动手，你就提醒我先把话听完。'],
  ['攀哥','我会提醒。但你也不用装得很客气，欠的账认，没同意的事就说没同意。我们来解决一件旧事，不是来演团圆。'],
  ['听歌','炫神在附近等电话。真有人来抢，追得上就直接把包截住；追不上也有车，能让他在前面路口挡一下，别一股脑跟着跑远。']
 ],end:[
  ['RY','原件都在，你们拿回去。我不回海豚帮，这个没变。旧公司的权益也先别交出去，至少等你们知道接下来怎么做。'],
  ['豚师','嗯。你以前垫的修车钱，Dina 会按账结；章鱼这些年的房租和电费，也一起列出来。不能每次都靠谁比较能忍，就让谁付。'],
  ['章鱼','这句话算你今天说得像样的一句。店不是谁的地盘，谁来接活、谁替它付钱、谁在里面吃饭，它就跟谁有关系。'],
  ['仙人','门上那句“海豚帮已经搬走了”，我还留着。下面新加了“偶尔回来”。不用抢着把过去刷掉，也不用每天守着它。'],
  ['Dina','营业款放柜台，维修费你决定什么时候付。以后有钱也别只看帮费数字，花在哪里、谁真拿到了，才算做完。'],
  ['豚师','先修门，剩下的慢慢来。今晚有人做饭吗？我修了三台设备，拆了一套房，到现在还没吃上一顿像样的。'],
  ['章鱼','饭有。你的活也有，吃完把碎玻璃扫了。']
 ]},
 four:[
  ['RY','我把那份原件带来了。收购不是想把你们赶走，是想把十年前没结完的生意收尾。合同闲着也要人维护，没收入时，最后总有人自己垫。'],
  ['豚师','这个我现在看到了。你垫的我认，章鱼垫的也认。但代理换锁、翻柜子，昨晚还来抢文件，你不能管这叫收尾。'],
  ['RY','他们越过了我说的范围，这事我会处理。你说不卖，我想听的是以后怎么经营，不是再喊一遍海豚帮。'],
  ['章鱼','昨晚我们已经接了三单。店小，赚得慢，但不是没人做。你先让我们试，账每个人都能看，没人逼你继续垫。'],
  ['攀哥','四个人的签字，就四个人谈。豚师也别拿兄弟二字盖过欠款。这回先分清公司的权益、店里的东西和每个人的钱，再决定往后怎么走。'],
  ['豚师','我不签出售。不是因为舍不得一个名字，是这次我愿意回来把活做完。你不回来也行，旧账我们结。'],
  ['RY','行，至少这是个回答。先把包收好。停车区那几个人从我们到这儿就没挪过，代理显然还没听懂“等一等”。']
 ],
 demolition:[
  ['小朋友','卡片背面有你画的平面图，蓝色线通到厨房左边，还有个小盒子的记号。你把文件藏到墙里了？'],
  ['豚师','当时那儿有个空腔，盒子塞进去以后，用薄板封上。后来又贴了装修板，看起来像一整面墙，所以我刚进门没认出来。'],
  ['小朋友','那就拆这面，不用把屋里每一样东西都找完吧？'],
  ['豚师','不用，沿地上那条旧蓝线，打掉尽头的隔墙就能看见盒子。室内隔墙、柜子、桌椅都能拆，想清路也行，外墙和楼板得留着。'],
  ['小朋友','我站门口。门口如果有人来堵，我给你看着。屋里的家具能拆，砸开的东西别再踩着过不去；找到盒子就走，别为了拆得干净把它落下。']
 ],
 orders:{
  '阿松':[['阿松','能扫了！我店里那台一天断三次，终于不用每个客人都举着手机给我看付款。工钱照说好的结。'],['豚师','你以前也是在这儿修？我怎么只记得我们每天吃粉。'],['阿松','吃粉之前总得有活干。你收钱，章鱼修，攀哥出去送，RY 晚上对账。这公司不是光凑个名字，真做过生意。']],
  '阿福':[['阿福','音箱没杂音了，这钱花得值。之前代理来问我签过什么文件，我还以为是要我证明你们以前在这儿闹过。'],['攀哥','不是证明我们闹过，是当年的仓储服务合同。你记得交接的人吗？'],['阿福','记得，他们最近还在茶子山配送。车上那张老标签都舍不得换，你们去看车，比在这儿猜靠谱。']],
  '小武':[['小武','对讲机好了，谢了。我得赶着送下一单，家里还等我吃饭。别说叫我回帮啊，偶尔来修东西、帮忙可以。'],['豚师','没叫你辞职。按单结钱，今天我也觉得这个办法挺好。'],['小武','那就好。顺便提醒一句，我上次签收看见旧公司的编号，海豚旧友设备服务。不是新公司，收购的人也在找这个，你们先把资料查全。']]
 },
 purchases:{
  shopStock:[['Dina','零件进了，营业可以多接一些单。柜台款我照旧记着，有空回来领；门坏了就先修，别让进货的钱白花。']],
  techniqueTraining:[['攀哥','组合拳练好了，第三拳别只顾着乱按，看准对方格挡的位置打。冲锋手蓄力时你先闪开，等他收不回来再反击。']],
  vehicleArmor:[['炫神','防撞杠装上了，能少伤一点车，不是让你拿车当推土机。运输的时候记得货也在车里。']],

  workbenchUpgrade:[['攀哥','配件装上了，定位稳一些，能接要求高一点的单。你还是看准了收手，工具贵也经不住乱拧。']],
  heavyGloves:[['豚师','这手套有点分量，拆隔墙正好。钱花出去了，总得让我少打一拳。']],
  hiredHelp:[['阿松','工钱收了，我们俩跟肝脏守店。你盯着冲进来的人，Dina 身边我们也会照看。']],
  reinforcedShutter:[['攀哥','加固板装好了，柜台后面也垫了一层。能多撑一会儿，不是让你站着看他们打。']],
  repairShop:[['章鱼','门面补好了，店能照常接活。旧宅的装修以后再谈，先别把修好的门又当靶子。']]
 },
 events:{
  budgetPaid:[['Dina','结好了，一万块周转金没动。登记、保全和旧维修账，我今晚一起办；你亲手赚出来的那份也写进账本。'],['听歌','他们的车刚拐进这条街。还有半分钟，落卷帘，把能挡路的车摆好。'],['豚师','今天不欠别人钱，也不把东西白送人。肝脏，跟我看门。']],
  deliveryMatch:[['听歌','车认对了，司机已经上车准备走。把车逼停，再开回来；车里那两箱记录我们要一起核对。']],
  cargoGrab:[['豚师','货抢下来了，先抱回店里。后面那几个人是跟你一起来的吧？'],['仙人','别在这里耗，矮栏和停着的车能挡他们，回店交货再算钱。']],
  cargoCrew:[['拿货的年轻人','把箱子留下！'],['豚师','老板的货你还说得跟自己的一样。追得上再说。']],
  garageQuietEscape:[['章鱼','记录和名字都拍清楚了，他们还没发现。趁这个时候走北侧坡道，别再绕回亮灯那边。'],['攀哥','东西拿到就撤，出口能出街。安静进来，也可以安静出去。']],
  garageEscape:[['章鱼','柜子记录和墙上的名字都拍下来了。灯这么亮，他们已经看见我们，走北侧坡道，那里真的能出街，别往中央封起来的区走。'],['攀哥','能开车就开车，出口有空间。东西拿到就撤，不必把每个人都打倒。']],
  collectors:[['收账的人','门一开就做生意了？代理让我们把文件柜收走，修东西也得先停。'],['章鱼','合同还没签，谁让你们搬我的东西？'],['豚师','客人的设备还在这儿，今天你们先搬自己出去。攀哥，看着台子。']],
  collectorsClear:[['攀哥','人退出去了，台上的设备没丢。最后一单修完，把工钱收齐，别让小武等到家里又打电话催。'],['章鱼','以后开门做生意，会遇见这种事。能把设备修好，也得能护住客人和柜台。']],
  deliveryStopped:[['听歌','配送车停了，车还能用。下你自己的车，再过去夺车，货箱还在后面，开到后勤层卸。']],
  unloadAmbush:[['Dina','我在卸货台这边，箱子搬过来。后面那几个人不是卸货工，小心，他们是来把记录拿回去的。'],['豚师','那先把人请出去，货不退。']],
  atriumRoute:[
   ['Dina','箱子收好了，你把车留在卸货区。我约到了今晚的调度，他手上有签收底单，能把这批记录和收货单位对起来。人在一层的茶湾咖啡等你。'],
   ['炫神','走 B 一北边的电梯上楼，出来就是商业中庭。穿过中庭找绿色招牌的茶湾咖啡，从玻璃店面中间进去。'],
   ['豚师','楼下追车打架，楼上喝咖啡。他这个夜班比我的舒服多了。'],
   ['Dina','别把人吓走就行。问清楚箱子上的编号，我在这里整理记录，等你消息。']
  ],
  atriumReceipt:[
   ['夜班调度','你就是来核对那两箱记录的？我只负责交接，不替代理谈价。箱子上的编号报一下，我给你看签收底单。'],
   ['豚师','H 零四。车上还贴着海豚旧友的旧标签，所以我们才拦的。'],
   ['夜班调度','对得上。收货单位写的是茶湾商厦，箱子是旧公司的采购和欠款记录。代理催我今晚转运，我还没签出去；底单这份副本你带走。'],
   ['豚师','这份有签字，终于不是谁嘴里的一句话了。谢谢，咖啡你慢慢喝。']
  ],
  officeEscape:[['听歌','邮件导出来了，警报也响了。带资料走员工楼梯，下到 B 一再出街，别回大厅门口跟他们排队打架。']],
  homeAmbush:[['小朋友','门口来人了，说你拿的盒子要交给他们。我没让他们进，他们已经开始挤了。'],['豚师','盒子在我这儿。挡路的家具砸掉也行，碎墙能震开近处的人，我们从门口出去。']],

  cargoCaught:[['店主','货都在，谢了。这一百是说好的，拿着。你别嫌小，今天少了这几箱货，我店里一下午都白忙。'],['豚师','不嫌，凭手脚挣的。我今天正缺这种钱。']],
  persuade:[['豚师','先去路边坐会儿。你堵着门骂，老板生意做不成，想劝你的人也进不来。有什么事等醒了说。'],['醉汉','我就站这儿！你是谁啊，还管我？'],['仙人','别在门口跟他拉扯，挪到旁边，真动手了拦一下就行。']],
  drunkFight:[['醉汉','你刚才推我了吧！'],['豚师','我是让你别往店里挤。你再抡手，我只能把你拦下来。'],['仙人','街口已经让开了，别把人追出去打，拦住就好。']],
  wrongCar:[['听歌','这辆标签对不上，文件袋也不是那一只。停车区还有车，站稳看清楚，不用重新跑一趟。']],
  breach:[['听歌','正门撞开了！车停在店里，碎墙不会再挡路。Dina 在左边柜台后面，先拦冲她过去的人，别只盯着车。']],
  wave1:[['肝脏','门口这批退了，右边后巷还有人往里走。你过去拦，我看着文件。']],
  wave2:[['攀哥','后巷守住了。停车区那辆车在加速，最后一批要撞正门，退开一点，等它停下来再上。']],
  bagCaught:[['豚师','包还在我手里，不用陪他们再跑一圈了。攀哥，看看里面有没有少。'],['攀哥','文件和章都齐。就在这里等 RY，炫神那辆车先别冲过来。']],
  bagTransfer:[['听歌','包转到停车区那辆灰车上了，车刚起步。上黄色车，直接开到它前面堵，不用贴着车尾跑。'],['炫神','我已经在西边路口横着停了，你把车逼过来也行，自己先截下来也行。包拿到我就把路让开。']]
 },
 clues:{
  window:[['豚师','窗台有新踩过的灰，旧插销也没换。有人从这里进去翻东西，再从正门换锁。电箱在旁边墙上，先看看线路有没有被动过。']],
  'outside-power':[['听歌','电箱没坏，只是店里那一路拉下来了。侧窗的旧木板能掀开，进去以后把店内配电恢复，正门暂时不用拆。']],
  'side-entry':[['豚师','木板松了，窗框里留了个口。先进去，找里面那只配电箱，把灯开了再翻柜子。']],
  'shop-power':[['仙人','灯亮了。柜子在左边，照片和账本留在桌上，看看他们到底翻走了哪一格。']],
  'shop-drawer':[['豚师','装杂物的没动，原来放文件的格子全翻过了。找得很准，知道这里曾经存过什么。']],
  'old-photo':[['豚师','那时我、攀哥、RY 和章鱼，刚把店租下来。大家都说先干几个月试试，没想到后来连“几个月”都拖成好多年。']],
  'old-ledger':[['攀哥','这本账留得挺全，修车、房租、采购都有。别只看你欠饭钱那一页，后面还有我们真正做过的生意。']],
  'garage-west':[['章鱼','西边亮了，这边绕停着的车能到零四柜。巡逻的人也看得更清楚，别直直迎着他走。']],
  'garage-east':[['章鱼','东边的灯也亮了，旧涂鸦在尽头的墙上。先核对柜子里的编号，再去看，别认成翻修后新画的那一面。']],
  'locker-04':[['章鱼','里面是旧采购单和车库平面图，零四写在东边墙角。按这个找，四个名字就在那儿；柜子本身没什么贵东西。']],
  'four-names':[['豚师','都还在，连我写歪的笔画都没补。墙上留着的是名字，柜子里留着的是账，这两样以前我总只看一样。']],
  'old-pc':[['豚师','电脑开不了了。以前一到晚上大家挤在这里打游戏，亏钱那天也一样，谁都不想先提白天的账。']],
  takeout:[['小朋友','外卖单背面写的不是菜，是今天进货多少、还差谁的钱。你们吃饭的时候，正事也没少聊。'],['豚师','只是我后来老把吃饭记得比正事清楚。']],
  'old-cards':[['小朋友','卡都过期了。照片背面画着房间平面图，蓝线指到厨房左边，旁边写“盒子封好，四个人一起开”。你看这个记号。'],['豚师','对，是那面封起来的隔墙。我知道怎么找了，不用把柜子翻第二遍。']],
  'visitor-log':[['Dina','日期和夜班司机那份副本对得上，来的都是同一家收购代理。我们要查的不是楼里所有人，就这一条交接。']],
  'staff-pass':[['听歌','临时门卡能开大厅那道门。从员工楼梯回办公室就行，不必出去绕楼。']],
  'contract-page':[['Dina','这页写清了买的是仓储和配送服务权益，不包含旧店屋里的杂物。代理不能因为收购合同，就自行换锁和搬东西。']],
  'project-code':[['听歌','H 零四，备注里写着原件未齐。四个签字人的东西还没集到他们手上，交易并没有完成。']],
  'email-title':[['Dina','邮件是 RY 发的，要求补齐四份原始文件和公司章以后再交割。备注地址在北京御园旧家，下一步去那里找盒子。']]
 },
 resume:[['攀哥','前面的调查还算数，不用重来。现在把正在做的事做完，新的装备和训练在旧店，能增强连击、车辆和营业。任务的调查还在，接下来把正在做的事做完。']],
 ambient:[['章鱼','回来吃饭可以，接活也欢迎。营业款留柜台，门面坏了记得修。别每次一来就把旧公司当成谜案查一遍。']]
};

conversations.resumeByObjective={
 'c207-break':conversations.demolition,
 'c205-tail-b1':[['Dina','前面拿到的车和货还算数。把配送车开进商业后勤层，到西侧卸货台下车，抱文件箱过来；代理的人还会追，别光顾着赶路。']],
 'c208-defend':[['攀哥','文件还在 Dina 身边，守店从这一轮继续。正门、后巷和撞门车分别来人，盯蓄力再反击，柜台边上的杂物也能拿来重击。']],
 'c209-car':[['听歌','包已经转进配送车了，你还没追丢。黄色车在停车区，先开到它前面堵，能在这段路截下就不用跟着跑完。']]
};
